        require(wrongAmount != c.currentBetLimit());
        require(address(this).balance >= wrongAmount);

        c.OpenToThePublic();

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.wager{value: wrongAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}
